cd /var/www/teletudo
php -r 'require "vendor/autoload.php"; $app=require "bootstrap/app.php"; $kernel=$app->make(Illuminate\Contracts\Console\Kernel::class); $kernel->bootstrap(); $rows=Illuminate\Support\Facades\DB::table("tt_LogDebug")->select("id","Caminho","Header","created_at")->whereIn("Caminho", ["AdmController", "AdmController::ListaEntregadoresAbertos"])->where(function($q){ $q->where("Header", "like", "%Entregadores online na ADM%")->orWhere("Header", "like", "%Entregadores online encontrados%"); })->orderByDesc("id")->limit(10)->get(); foreach($rows as $row){ echo $row->id," | ",$row->Caminho," | ",$row->Header," | ",$row->created_at,PHP_EOL; } if (count($rows) === 0) { echo "NO_MATCHING_ONLINE_LOGS", PHP_EOL; }'